          "low": -2,
          "high": 4,
          "choices": null
        },
        {
          "param": "frac_guard",
          "low": 0,
          "high": 4,
          "choices": null
        },
        {
          "param": "rounding",
          "low": null,
          "high": null,
          "choices": ["trunc", "round"]
        },
        {
          "param": "m",
          "low": 2,
          "high": 8,
          "choices": null
        }
      ],
      "budget_share": 0.8,
      "why": "pipelined_m registers every m stages, so it keeps the same datapath as pipelined but uses far fewer flip-flops; with the loose 1 MSPS throughput constraint, large m minimizes area. This family should dominate pipelined for the min-area objective."
    },
    {
      "family": "pipelined",
      "ranges": [
        {
          "param": "data_width",
          "low": 11,
          "high": 16,
          "choices": null
        },
        {
          "param": "n_iter",
          "low": 10,
          "high": 18,
          "choices": null
        },
        {
          "param": "angle_guard",
          "low": -2,
          "high": 4,
          "choices": null
        },
        {
          "param": "frac_guard",
          "low": 0,
          "high": 4,
          "choices": null
        },
        {
          "param": "rounding",
          "low": null,
          "high": null,
          "choices": ["trunc", "round"]
        }
      ],
      "budget_share": 0.2,
      "why": "Baseline fully pipelined family (equivalent to pipelined_m with m=1); included to confirm dominance and provide a reference point for the merged front."
    }
  ],
  "rationale": "The spec's only binding constraint is max_abs_err <= 2^-10 (accuracy_bits >= 10); the 1 MSPS throughput floor is trivially met by any pipelined variant. Accuracy depends only on data_width, n_iter, angle_guard, frac_guard and rounding, so both families share the same accuracy landscape. pipelined_m strictly reduces flip-flop count versus pipelined by registering every m stages, so it should dominate for the min-area objective. The chosen ranges (W 11..16, N 10..18) bracket the expected accuracy boundary around 10 bits, while guards and rounding let the search trade area for accuracy. The 80/20 budget split focuses on pipelined_m while keeping a small baseline on pipelined."
}
